import {recipes,layer} from './ingredients.js';
// Single source of truth (choosing another product starts its Personalização over; the cart stays): { product: Receita id, editing, removed: applied ids, draft: ids in the open editor, combo, drink: Bebida do combo ('' until chosen; only with the combo), drinkError: the combo was added without a drink, cart }.
export const initial={product:'whopper',removed:[],draft:[],editing:false,combo:false,drink:'',cart:[]};
export function reducer(s,a){switch(a.type){case'select':return s.product===a.product||!recipes[a.product]?s:{...s,product:a.product,removed:[],draft:[],editing:false};case'open':return {...s,editing:true,draft:[...s.removed]};case'toggle':if(!s.editing||layer(recipes[s.product],a.id)?.locked)return s;return {...s,draft:s.draft.includes(a.id)?s.draft.filter(x=>x!==a.id):[...s.draft,a.id]};case'remove':return s.draft.includes(a.id)?s:reducer(s,{type:'toggle',id:a.id});case'reset':return {...s,draft:[]};case'apply':return {...s,editing:false,removed:[...s.draft]};case'cancel':return {...s,editing:false,draft:[]};case'combo':return {...s,combo:a.value,drink:a.value?s.drink:'',drinkError:false};case'drink':return s.combo?{...s,drink:a.value,drinkError:false}:s;case'add':if(s.combo&&!s.drink)return {...s,drinkError:true};return {...s,cart:[...s.cart,{product:s.product,removed:[...s.removed],combo:s.combo,price:price(s)}]};case'delete':return {...s,cart:s.cart.filter((_,i)=>i!==a.index)};default:return s}}
export const comboFee=1200,drinks=['Coca-Cola','Coca-Cola Zero','Sprite','Fanta Laranja','Natural One Laranja','Natural One Uva','Água de Copo'],money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),price=s=>recipes[s.product].price+(s.combo?comboFee:0);
